  openList.sort(function(x,y){var rx=RANK[x.priority]==null?9:RANK[x.priority],ry=RANK[y.priority]==null?9:RANK[y.priority];if(rx!==ry)return rx-ry;var dx=dayDiff(x.due_date),dy=dayDiff(y.due_date);return (dx==null?9999:dx)-(dy==null?9999:dy);});
  var diaWeek=0,workers7=0,nW7=0;
  for(var d0=0;d0<diaries.length;d0++){var da=diaries[d0].answers||{};var dd=dayDiff(da.date);if(dd!=null&&dd>=-6&&dd<=0){diaWeek++;if(da.workers_on_site!=null&&da.workers_on_site!==''){workers7+=num(da.workers_on_site);nW7++;}}}
