  var delWeek=0,delIssues=0;
  for(var e0=0;e0<delivs.length;e0++){var ea=delivs[e0].answers||{};var ed=dayDiff(ea.delivery_date);if(ed!=null&&ed>=-6&&ed<=0)delWeek++;if(ed!=null&&ed>=-30&&ed<=0&&ea.issues&&String(ea.issues).trim())delIssues++;}
